{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

{
  "rules": [
    {
      "id": "plank-form",
      "description": "@planks annotation must be in a docblock immediately preceding a declaration, and its string must match a current step-definition pattern exactly.",
      "severity": "error",
      "check": "plank-join"
    },
    {
      "id": "plank-coverage",
      "description": "Every behaviour-bearing step-definition pattern must have at least one @planks annotation in implementation.",
      "severity": "error",
      "check": "plank-join"
    },
    {
      "id": "provisional-plank-liveness",
      "description": "@planks-provisional reference must name a scenario that still carries @captain.",
      "severity": "error",
      "check": "plank-join"
    },
    {
      "id": "verification-debt-no-guessed-delay",
      "description": "Step definitions must not contain guessed literal delays (setTimeout with numeric literal). Prefer observing a signal.",
      "severity": "warn",
      "patterns": ["setTimeout\\(\\s*\\d+\\s*\\)", "await new Promise\\(.*setTimeout.*\\)"]
    },
    {
      "id": "verification-debt-no-hard-dependency-creation",
      "description": "Verification support must not create expensive dependencies internally; use the production creation seam.",
      "severity": "warn",
      "check": "manual-review"
    }
  ],
  "meta": {
    "format": "shipshape-verification-conformance-v1",
    "engine": "text-pattern-fallback",
    "weakness": "Text-pattern rules cannot detect AST structure; docblock placement and indirect creation are checked by plank-join mjs"
  }
}
